WITH filtered AS (SELECT id, event_type, page, event_time, duration_sec, COALESCE(duration_sec, 0) AS duration_sec_filled, COALESCE(page, 'OTHER') AS page_filled FROM web_events WHERE event_type = 'page_view') SELECT * FROM (SELECT page, event_type, duration_sec FROM filtered) src PIVOT (SUM(duration_sec) AS amount, COUNT(1) AS item_count FOR event_type IN ('add_to_cart', 'search'));
